abhinav_1_3 = {
    'hi': '।।8.1--8.3।। श्री अभिनवगुप्त कहते हैं: अर्जुन के सप्त प्रश्नों (ब्रह्म, अध्यात्म, कर्म, अधिभूत, अधिदैव, अधियज्ञ और प्रयाणकाल में भगवत्प्राप्ति) के उत्तर में भगवान् कहते हैं: परम अक्षर ही परब्रह्म है, अपना शुद्ध स्वरूप अध्यात्म है, और भूतों के भाव का उद्भव करने वाला विसर्ग कर्म कहलाता है।',
    'en': '8.1--8.3 Sri Abhinavagupta states: In response to Arjuna\"s seven queries (Brahman, Adhyatma, Karma, Adhibhuta, Adhidaiva, Adhiyajna, and divine remembrance at death), the Lord explains that the Supreme Imperishable is Brahman, one\"s essential nature is Adhyatma, and the creative offering that originates cosmic existences is Karma.',
    'be': '৮.১--৮.৩ শ্রী অভিনবগুপ্ত বলেছেন: অর্জুনের সপ্ত প্রশ্নের (ব্রহ্ম, অধ্যাত্ম, কর্ম, অধিভূত, অধিদৈব, অধিয়জ্ঞ এবং প্রয়াণকালে ভগবদ্ প্রাপ্তি) উত্তরে ভগবান বলেছেন: পরম অক্ষরই পরব্রহ্ম, নিজের শুদ্ধ রূপ অধ্যাত্ম, এবং ভূতের ভাবের উদ্ভবকারী বিসর্গ কর্ম নামে পরিচিত।',
    'ka': '೮.೧--೮.೩ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಅರ್ಜುನನ ಏಳು ಪ್ರಶ್ನೆಗಳಿಗೆ (ಬ್ರಹ್ಮ, ಅಧ್ಯಾತ್ಮ, ಕರ್ಮ, ಅಧಿಭೂತ, ಅಧಿದೈವ, ಅಧಿಯಜ್ಞ ಹಾಗೂ ಪ್ರಯಾಣಕಾಲದಲ್ಲಿ ಭಗವತ್ಪ್ರಾಪ್ತಿಯು) ಉತ್ತರವಾಗಿ ಭಗವಂತನು ಹೇಳುತ್ತಾನೆ: ಪರಮ ಅಕ್ಷರವೇ ಪರಬ್ರಹ್ಮ, ತನ್ನ ಶುದ್ಧಸ್ವರೂಪವೇ ಅಧ್ಯಾತ್ಮ, ಹಾಗೂ ಭೂತಗಳ ಭಾವವನ್ನು ಉದ್ಭವಿಸುವ ವಿಸರ್ಗವೇ ಕರ್ಮವೆನಿಸುತ್ತದೆ'
}

abhinav_4_5 = {
    'hi': '।।8.4--8.5।। श्री अभिनवगुप्त कहते हैं: क्षर भाव अधिभूत है, पुरुष अधिदैव है, और देह में स्थित परमेश्वर अधियज्ञ हैं। जो अंतकाल में भगवान् का निरंतर स्मरण करते हुए देह त्यागता है, वह संशयहीन प्रभु-भाव को प्राप्त होता है।',
    'en': '8.4--8.5 Sri Abhinavagupta states: Perishable object is Adhibhuta, cosmic Purusha is Adhidaiva, and the Lord in the body is Adhiyajna. One who leaves the body at death meditating on the Lord attains His divine state without doubt.',
    'be': '৮.৪--৮.৫ শ্রী অভিনবগুপ্ত বলেছেন: ক্ষর ভাব অধিভূত, পুরুষ অধিদৈব, এবং দেহে স্থিত পরমেশ্বর অধিয়জ্ঞ। যে অন্তকালে ভগবানের নিরন্তর স্মরণ করতে করতে দেহ ত্যাগ করে, সে সংশয়হীন প্রভু-ভাব প্রাপ্ত হয়।',
    'ka': '೮.೪--೮.೫ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಕ್ಷರ ಭಾವವೇ ಅಧಿಭೂತ, ಪುರುಷನೇ ಅಧಿದೈವ, ಹಾಗೂ ದೇಹದಲ್ಲಿ ಸ್ಥಿತನಾದ ಪರಮೇಶ್ವರನೇ ಅಧಿಯಜ್ಞನಾಗಿದ್ದಾನೆ. ಅಂತಕಾಲದಲ್ಲಿ ಭಗವಂತನನ್ನು ನಿರಂತರವಾಗಿ ಸ್ಮರಿಸುತ್ತಾ ದೇಹತ್ಯಾಗ ಮಾಡುವವನು ಸಂಶಯವಿಲ್ಲದೆ ಪ್ರಭುಭಾವವನ್ನು ಪಡೆಯುತ್ತಾನೆ'
}

